  return hd_sqrt(R(.5)*(sum+hd_sqrt(hd_max(R(0),sum*sum-R(4)*a2*bn*bn/p[0]))));
}
// Returns unscaled eight-variable MHD flux, excluding all cleaning energy.
// reason:0 HLLD/upwind;1 near-degenerate denominator;2 nonphysical star state;
// 3 inconsistent wave ordering;4 nonfinite result. Failure returns HLLE.
template<class R> HD_FN void hd_flux(const R*l,const R*r,const R*n,R bn,R gamma,R*f,int&reason){
  reason=0;R ul[8],ur[8],fl[8],fr[8],hlle[8];
  hd_state_flux(l,n,bn,gamma,ul,fl);hd_state_flux(r,n,bn,gamma,ur,fr);
  R vl=hd_dot(l+1,n),vr=hd_dot(r+1,n),cl=hd_fast(l,bn,gamma),cr=hd_fast(r,bn,gamma);
  R sl=hd_min(vl-cl,vr-cr),sr=hd_max(vl+cl,vr+cr);
  if(sl>=R(0)){for(int x=0;x<8;++x)f[x]=fl[x];return;}
  if(sr<=R(0)){for(int x=0;x<8;++x)f[x]=fr[x];return;}
  for(int x=0;x<8;++x)hlle[x]=(sr*fl[x]-sl*fr[x]+sl*sr*(ur[x]-ul[x]))/(sr-sl);
  R ptl=l[4]+R(.5)*hd_dot(l+5,l+5),ptr=r[4]+R(.5)*hd_dot(r+5,r+5);
  R sdl=sl-vl,sdr=sr-vr,den=sdr*r[0]-sdl*l[0];
  R scale=hd_max(hd_abs(sdr*r[0]),hd_abs(sdl*l[0]));
  if(hd_abs(den)<=R(1e-6)*scale){reason=1;}
  R sm=reason?R(0):(r[0]*sdr*vr-l[0]*sdl*vl+ptl-ptr)/den;
  if(!hd_finite(sm)||sm<sl||sm>sr)reason=3;
  R pts=R(.5)*(ptl+l[0]*sdl*(sm-vl)+ptr+r[0]*sdr*(sm-vr));
  if(!(pts>R(0)&&hd_finite(pts)))reason=2;
  R us[2][8],vs[2][3],bs[2][3],vb[2],root[2];
  for(int side=0;side<2&&!reason;++side){const R*p=side?r:l;const R*u=side?ur:ul;
    R s=side?sr:sl,vn=side?vr:vl,sd=s-vn,sdm=s-sm;
    R pressure_scale=hd_max(hd_abs(p[0]*sd*sdm),hd_max(bn*bn,hd_abs(pts)));
    R d=p[0]*sd*sdm-bn*bn;
    if(hd_abs(sdm)<=R(1e-6)*hd_max(hd_abs(s),hd_abs(sm))||hd_abs(d)<=R(1e-6)*pressure_scale){reason=1;break;}
    us[side][0]=p[0]*sd/sdm;
    if(!(us[side][0]>R(0)&&hd_finite(us[side][0]))){reason=2;break;}
    R velocity_factor=bn*(sm-vn)/d,magnetic_factor=(p[0]*sd*sd-bn*bn)/d;
    for(int j=0;j<3;++j){R vt=p[1+j]-vn*n[j],bt=p[5+j]-bn*n[j];
      vs[side][j]=sm*n[j]+vt-bt*velocity_factor;
      bs[side][j]=bn*n[j]+bt*magnetic_factor;
      us[side][1+j]=us[side][0]*vs[side][j];us[side][5+j]=bs[side][j];}
    vb[side]=hd_dot(vs[side],bs[side]);R pt=side?ptr:ptl;
    us[side][4]=(sd*u[4]-pt*vn+pts*sm+bn*(hd_dot(p+1,p+5)-vb[side]))/sdm;
    if(!hd_physical(us[side],gamma)){reason=2;break;}root[side]=hd_sqrt(us[side][0]);
  }
  if(reason){for(int x=0;x<8;++x)f[x]=hlle[x];return;}
  R sal=sm-hd_abs(bn)/root[0],sar=sm+hd_abs(bn)/root[1];
  if(sal<sl||sar>sr||sal>sm||sar<sm){reason=3;for(int x=0;x<8;++x)f[x]=hlle[x];return;}
  R sign=bn>R(0)?R(1):R(-1),vss[3],bss[3],uss[2][8],sum=root[0]+root[1];
  for(int j=0;j<3;++j){R vtl=vs[0][j]-sm*n[j],vtr=vs[1][j]-sm*n[j];
    R btl=bs[0][j]-bn*n[j],btr=bs[1][j]-bn*n[j];
    vss[j]=sm*n[j]+(root[0]*vtl+root[1]*vtr+sign*(btr-btl))/sum;
    bss[j]=bn*n[j]+(root[0]*btr+root[1]*btl+sign*root[0]*root[1]*(vtr-vtl))/sum;}
  R vbss=hd_dot(vss,bss);
  for(int side=0;side<2;++side){uss[side][0]=us[side][0];
    for(int j=0;j<3;++j){uss[side][1+j]=us[side][0]*vss[j];uss[side][5+j]=bss[j];}
    uss[side][4]=us[side][4]+(side?R(1):R(-1))*root[side]*sign*(vb[side]-vbss);
    if(!hd_physical(uss[side],gamma))reason=2;}
  if(reason){for(int x=0;x<8;++x)f[x]=hlle[x];return;}
  for(int x=0;x<8;++x){R fs_l=fl[x]+sl*(us[0][x]-ul[x]),fs_r=fr[x]+sr*(us[1][x]-ur[x]);
    if(sal>R(0))f[x]=fs_l;else if(sar<R(0))f[x]=fs_r;
    else{R fss_l=fs_l+sal*(uss[0][x]-us[0][x]),fss_r=fs_r+sar*(uss[1][x]-us[1][x]);
      f[x]=sm>R(0)?fss_l:(sm<R(0)?fss_r:R(.5)*(fss_l+fss_r));}
    if(!hd_finite(f[x]))reason=4;}
  if(reason)for(int x=0;x<8;++x)f[x]=hlle[x];
}
#undef HD_FN
